  WITH n AS (INSERT INTO cenarios_planejamento (nome, descricao, unidade_id, tipo, estado, versao, cenario_origem_id, periodo_inicio, periodo_fim, autor_id, aprovado_por_id, publicado_em, parametros, indicadores, resultado_validacao, lock_version) VALUES ('DEMO-Planejamento 2026/2', NULL, (SELECT id FROM unidades WHERE codigo = 'BEIRA-MAR'), 'planejamento', 'em_elaboracao', 1, NULL, '2026-08-03', '2026-12-18', NULL, NULL, NULL, NULL, NULL, NULL, 0) RETURNING id) INSERT INTO _demo_ids SELECT 'cenarios_planejamento', 3, id FROM n;
  DROP TABLE _demo_ids;
END $$;

-- 3) Conferência
SELECT (SELECT count(*) FROM cursos WHERE codigo LIKE 'DEMO-%') AS cursos,
       (SELECT count(*) FROM unidades_curriculares WHERE codigo LIKE 'DEMO-%') AS ucs,
       (SELECT count(*) FROM turmas WHERE codigo LIKE 'DEMO-%') AS turmas,
       (SELECT count(*) FROM instrutores WHERE matricula LIKE 'DEMO-%') AS instrutores,
       (SELECT count(*) FROM cenarios_planejamento WHERE nome LIKE 'DEMO-%') AS cenarios;
